package hcl

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// ModuleRecord represents a single module entry in .terraform/modules/modules.json.
type ModuleRecord struct {
	Key     string `json:"Key"`
	Source  string `json:"Source"`
	Version string `json:"Version,omitempty"`
	Dir     string `json:"Dir"`
}

// ModulesManifest represents the .terraform/modules/modules.json schema generated by terraform init.
type ModulesManifest struct {
	Modules []ModuleRecord `json:"Modules"`
}

// LoadModulesManifest reads and parses .terraform/modules/modules.json if it exists.
// Returns nil, "", nil if the manifest file does not exist.
func LoadModulesManifest(rootDir string) (*ModulesManifest, string, error) {
	manifestPath := filepath.Join(rootDir, ".terraform", "modules", "modules.json")
	data, err := os.ReadFile(manifestPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, "", nil
		}
		return nil, "", fmt.Errorf("failed to read modules manifest %q: %w", manifestPath, err)
	}

	var manifest ModulesManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return nil, manifestPath, fmt.Errorf("failed to parse modules manifest %q: %w", manifestPath, err)
	}
	return &manifest, manifestPath, nil
}

// DiscoverModuleFiles inspects .terraform/modules/modules.json and discovers all candidate .tf files inside registered child modules.
// It returns the list of file paths, the list of discovered module keys, and any error encountered.
func DiscoverModuleFiles(rootDir string) ([]string, []string, error) {
	manifest, _, err := LoadModulesManifest(rootDir)
	if err != nil || manifest == nil {
		return nil, nil, err
	}

	var allModuleFiles []string
	var moduleNames []string
	visitedDirs := make(map[string]struct{})

	for _, mod := range manifest.Modules {
		// Skip root module (Key is empty or Dir is "." or "")
		if mod.Key == "" || mod.Dir == "." || mod.Dir == "" {
			continue
		}

		var modDir string
		if filepath.IsAbs(mod.Dir) {
			modDir = mod.Dir
		} else {
			modDir = filepath.Clean(filepath.Join(rootDir, mod.Dir))
		}

		if _, seen := visitedDirs[modDir]; seen {
			continue
		}
		visitedDirs[modDir] = struct{}{}

		info, err := os.Stat(modDir)
		if err != nil || !info.IsDir() {
			continue
		}

		entries, err := os.ReadDir(modDir)
		if err != nil {
			continue
		}

		foundFiles := false
		for _, entry := range entries {
			if entry.IsDir() {
				continue
			}
			name := entry.Name()
			if isCandidateFile(name) {
				allModuleFiles = append(allModuleFiles, filepath.Join(modDir, name))
				foundFiles = true
			}
		}

		if foundFiles {
			moduleNames = append(moduleNames, mod.Key)
		}
	}

	return allModuleFiles, moduleNames, nil
}
